def word_frequency(text: str) -> dict[str, int]:
    from string import punctuation

    counts: dict[str, int] = {}
    for word in text.split():
        cleaned = word.strip(punctuation).lower()
        if cleaned:
            counts[cleaned] = counts.get(cleaned, 0) + 1
    return counts
